sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT
initial=json.loads((ROOT/'config/authored_batches/S7_032_independent_answers.json').read_text())['records']
by={r['question_id']:r for r in initial}
out=[]
def add(q,stem,cid,labels,solution,knowledge,ambiguity='',options=None,counts=None,vector=None,rows=None,citations=None):
 r=by[q];choices={}
 if options:
  for i,(v,truth,reason) in enumerate(options,1):choices[str(i)]=dict(value=v,verdict='適切' if truth else '不適切',reason=reason)
 elif counts is not None:
  for i,n in enumerate(counts,1):
   choices[str(i)]=dict(value=str(n)+'件',verdict='個数を比較',reason=('判定の合計と対応する。' if str(i)==('4' if q=='H25-REG-APT-07' else r['independent_answer']) else '判定の合計とは対応しない。')+solution)
 else:
  for i,row in enumerate(rows,1):
   diff=[chr(0x30a2+j) for j,(a,b) in enumerate(zip(row,vector)) if a!=b]
   choices[str(i)]=dict(value='・'.join('正' if x=='T' else '誤' for x in row),verdict='適切な組合せ' if row==vector else '組合せが不一致',reason='各記述の判定は'+vector+'である。'+('全ての列が一致する。' if not diff else '原典の列順で'+str([j+1 for j,(a,b) in enumerate(zip(row,vector)) if a!=b])+'列目が異なる。')+solution)
 out.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions={'原典条件':'問題幹、否定、ア等の記号順、5選択肢と個数又は表の全行を原典16画像で確認した。','論理条件':knowledge,'法の時点':'出題時の制度を保持。現行取得基準日は2026-10-12。2020年施行の期間変更を別記する。'},choices=choices,figures='文字表又は記述問題であり図なし。組合せの各行は原典画像の列順を保持する。',ambiguity=ambiguity,evidence=[r['image']],core_concept=stem,required_knowledge=knowledge,solution=solution,answer_reason=solution,independent_answer=r['independent_answer'],independent_solution_note='公式参照前の原典画像確認と初回保存。'+r['reason']+' 初回値は訂正又は資料確認後も改変せず保存する。',learning_points='対象物、責任主体、欠陥・損害・因果関係、免責、期間制限を順に分けて判定する。対象外という結論から事故予防や他法の責任の不存在を導かない。',theory_references=['theory:pl:'+x for x in labels],discipline_id='apt_3',concept_id=cid,cross_concepts=[],classification_reason='原典の中心は製品事故、対象物と責任主体、欠陥と賠償、製品安全の予防である。安全・リスクapt_3へ分類し、製造物責任の共通理論に接続する。CSR一般や環境問題へ製品安全の各条件を一括しない。',calculation='false',figure='false',law='true',evaluation=dict(knowledge_novelty='2',reasoning_steps='3' if counts is not None else '2',calculation_load='0',figure_reading='0',difficulty='3' if counts is not None else '2',difficulty_reason='法律要件を複数の事例へ対応させる負荷を評価。数式計算はない。原典の解釈疑義と未取得規格は難易度とは別に保存する。'),citations=citations or ['pl_statute','pl_qa','pl_definitions2018'],foundationality='high',transferability='high'))
add('H23-REG-APT-08','PL法の立証・対象・自損・輸入者・欠陥の5記述を正誤表に対応させる。','pl_proof',['proof','scope','selfdamage','producer','defect'], 'アは過失の証明が法の変化であるという説明が誤り、イは電気と単体ソフトまで対象にする全称が誤りである。ウはテレビだけの損害が3条ただし書の対象外、エは輸入者を除外する点が誤りである。オは通常有すべき安全性を欠陥の基準とし、適切である。FFFFTに対応する5を選ぶ。','原典列順ア・イ・ウ・エ・オ。単体ソフトと組込み製品、輸入と単なる販売、品質と安全を分ける。',vector='FFFFT',rows=['TTFFT','FFTFT','TFFFT','FTTFF','FFFFT'])
add('H24-REG-APT-07','8対象のうちPL法の製造物に該当しない数を求める。','pl_scope',['scope','software','processing','attachment','repair'], 'アのソフト単体、ウの宅地、キの未加工トマトは対象外である。イの缶詰、オのロボット、カの有体のガスやガソリン、クの取り付け前に引き渡されたサッシ等は対象になり得る。エを修理された製品そのものと読むと製造物性が残り、対象外3件・初回3となる。公式4は対象外4件であり、エを修理行為又は修理起因の欠陥について読む場合の追加除外と整合する。消費者庁Q&Aは中古品の製造物性を肯定し、引渡時の欠陥と後の修理を分けている。','5候補は対象外1、2、3、4、5件。名称と責任成立の条件を分ける。','初回3・公式4。使用者が修理した製品という対象名だけでは製造物性の消滅を導けない。修理行為の非該当性又は修理起因の不具合との読み分けをAstra査読事項として保持する。',counts=[1,2,3,4,5])
add('H25-REG-APT-07','PL法の8記述のうち不適切な数を数える。','pl_scope',['proof','scope','processing','development','selfdamage','producer'], 'アは電気やソフトまで対象にする点、ウは開発危険免責を否定する点、エは過失立証の制度説明、カは製品自体だけの損害を含める点、キは輸入者除外が不適切である。イは予見可能な誤使用への安全確保、クは安全と無関係の品質不具合の除外を述べる。オの単なる冷凍冷蔵を未加工とする説明は、逐条解説の物理3頁を画像で確認して適切と訂正した。初回はオも誤りとして6件・5であったが、訂正後は5件・4となる。公式4との一致とは独立した一次資料上の訂正である。','候補は不適切2、3、4、5、6件。冷凍冷蔵とハム等の加工を対比する。','初回5を保持する。逐条解説により冷凍冷蔵の初回分類を訂正し、5件・候補4となる。イの品質上の欠陥は安全性に関わる範囲として読む必要があり、広義の品質不良全てにPL責任を認めない。',counts=[2,3,4,5,6])
add('H26-REG-APT-07','PL法の5記述から開発危険の免責を否定する文を選ぶ。','pl_development',['scope','producer','defect','development','proof'], '1〜3は製造加工動産、輸入者、通常の安全性という要件を述べる。4は引渡時の科学技術で認識不能でも免責できないとするため、4条1号と反する。5は過失立証の不要という要点を述べるが、欠陥の存在だけで全責任が成立するという独立した法律説明ではなく、損害と因果関係を前提とした省略表現として読む。','最も不適切な単一候補を選ぶ。','5の欠陥存在だけで請求できるという省略には損害と因果関係の条件を補う必要がある。公式4と初回4は保持する。',options=[('製造又は加工された動産であり、不動産は除く',True,'2条1項の定義である。'),('製造加工と輸入の事業者を含む',True,'輸入者も2条3項1号の対象となる。'),('通常の安全性の不足が欠陥である',True,'安全と無関係な品質不良は区別する。'),('認識不能でも免責されない',False,'4条1号は所定の証明による開発危険の免責を定める。'),('過失立証は不要で欠陥を立証する',True,'制度変化は正しいが、損害と因果関係を省略している。')])
add('H28-REG-APT-07','OEM表示・無体物・不動産・未加工物の4記述を組合せに対応させる。','pl_producer',['producer','scope','processing'], 'アのOEM販売者は製造業者等に当たらないという一律除外は誤りである。製造業者と誤認させる表示等の要件を満たせば対象となる。イの無体エネルギー・ソフト・修理サービス、ウの不動産、エの未加工農林水産物と採掘したままの鉱物の除外は適切である。FTTTに対応する5を選ぶ。','列順ア・イ・ウ・エ。OEMの条件付該当性。',vector='FTTT',rows=['TTTF','TTFT','TFTT','TTTT','FTTT'])
add('H29-REG-APT-08','PL法の目的・立証・対象・誤使用・開発危険から不適切な記述を選ぶ。','pl_development',['framework','proof','scope','defect','development'], '1は法の目的、3は対象の定義である。2は過失から欠陥と損害の因果関係へ立証の中心が移る説明、4は通常予見される誤使用への安全確保である。5の認識不能でも責任を負うという一律の結論は開発危険の免責を落としており不適切である。','最も不適切な候補。品質の欠陥は安全性に関わる範囲で理解する。','2は施行前の救済を709条で代表し、契約責任等を省略している。4の品質上の欠陥は安全性に関わるものと読む。文の省略範囲を査読事項に保持する。',options=[('法は被害者保護等を目的とする',True,'1条の趣旨である。'),('欠陥と損害の関係を立証する',True,'過失立証不要の要点は適切だが、以前の契約責任等を一括否定しない。'),('対象は製造加工動産である',True,'2条1項の定義である。'),('予見可能な誤使用にも安全確保が必要',True,'通常予見される使用形態を総合判断する。品質一般とは区別する。'),('認識不能でも責任を免れない',False,'4条の免責条件を無視している。')])
add('H30-REG-APT-09','PL法の6記述で、予見可能な誤使用と安全性の定義以外の誤りを数える。','pl_time',['defect','development','proof','time','producer'], 'アとカは適切である。イは開発危険、ウは過失立証、オは輸入者について誤る。エは通常のテレビ火災に購入後10年を過ぎても欠陥の証明だけで請求できると断定し、引渡し起算の期間制限と他の成立要件を無視する。したがって不適切はイ・ウ・エ・オの4件で候補3となる。購入と引渡しは同一日と決め付けず、潜伏性損害の例外とも分ける。','5候補は不適切2、3、4、5、6件。出題は2020年改正前。','エは購入日と製造業者等の引渡し日の関係を明示しない。一般のテレビ火災と欠陥だけで請求できるとの断定として不適切と判定し、期間特則や中断等の個別事情の不存在まで推測しない。',counts=[2,3,4,5,6],citations=['pl_statute','pl_qa','pl_transition2020'])
add('R01-REG-APT-03','8事故でPL法の賠償責任に該当しない事例の数を求める。','pl_scope',['scope','software','attachment','processing','repair'], 'アの輸入車、ウの電動シャッター、カの組込みソフトによるロボットは、製造時の欠陥と負傷の因果関係を前提にPL責任の対象となる。イの宅地、エの未加工鶏卵、オの保守サービス、キの電力、クの未加工養殖魚は対象外で5件である。候補4を選ぶ。保守ミスの責任や食品の安全確保が消えるという意味ではない。','対象外数候補8、7、6、5、4。製造欠陥と後の保守ミスを分ける。',counts=[8,7,6,5,4])
add('R01-RET-APT-07','PL法の不動産例外・欠陥・時効・原子力・民法の5記述から正しい数を求める。','pl_time',['scope','defect','time','otherlaw'], 'アの戸建て住宅耐震違反をPL法の例外とする説明は誤りであり、ウの時効なしも誤りである。イの欠陥の定義、エの原子力損害へのPL法不適用、オの民法の補充適用は適切である。正しい3件が候補3に対応する。原子力損害は特別法4条3項を確認し、住宅の他法による責任とは分ける。','正しい数候補1、2、3、4、5。通常試験と再試験を別IDで保持。',counts=[1,2,3,4,5],citations=['pl_statute','pl_qa','pl_nuclear_statute','pl_transition2020'])
add('R02-REG-APT-06','PL法の目的・因果関係・開発危険・民法・海外制度から最も不適切な文を選ぶ。','pl_proof',['proof','development','otherlaw'], '1は目的、2は欠陥と損害の因果関係の証明、3は開発危険の免責、4は民法の補充であり適切である。5は国際的に統一された規定なので日本法だけに従えばよいと断定する。対象範囲や責任の条件は国ごとに確認すべきであり、5が不適切である。','単一の不適切文。科学技術の認識不能は製造業者側が証明する。',options=[('被害者保護等を目的とする',True,'1条の趣旨である。'),('過失の有無にかかわらず因果関係を証明する',True,'欠陥・損害の関係の証明は必要である。'),('認識不能の開発危険を証明すれば免責',True,'4条1号の条件を述べる。'),('特段の定めがない責任は民法を適用',True,'6条の補充規定である。'),('国際共通なので日本法だけでよい',False,'外国の対象や要件の違いを無視している。')])
add('R02-REG-APT-12','製品安全の社会的責任に関する7取組から不適切な数を求める。','product_csr',['csr','framework'], 'アの法令順守を超えるリスク低減、イの消費者期待を踏まえた基準、ウの事故予防、エの対話、オの将来と弱者への配慮、カの緊急時対応、キの苦情解決手段は、いずれも問題が提示する社会的責任の定義と整合する。賠償責任を負わないことだけへ活動を限定しない。不適切は0件で候補1となる。','問題提示のISO26000の定義を条件として用いる。候補0、1、2、3、4件。','ISO26000原規格全文と経済産業省研修PDF全文は未取得。問題提示定義と全7取組は原典確認し、索引による補助確認の範囲を超えて規格版照合済みとは扱わない。',counts=[0,1,2,3,4],citations=['pl_product_csr2016'])
add('R03-REG-APT-08','付合・組込みソフト・再生品・修理の4記述を正誤表で判定する。','pl_repair_recycle',['attachment','software','recycle','repair'], 'アは取り付け後も引渡時の動産の欠陥の責任が問題となるため正しい。イは組込みソフトの不具合と製品事故の因果関係を条件にして正しい。ウは最後の再生業者が全て責任を負うと断定するが、元の製品の欠陥と損害の因果関係があれば元の製造業者にも責任が生じ得るため誤りである。エは性質回復維持という修理サービス自体を指し正しい。TTFTが3に対応する。','列順ア・イ・ウ・エ。修理された元の製品の対象性とは区別する。',vector='TTFT',rows=['TFTT','FTTF','TTFT','TFTF','FTFT'])
add('R04-REG-APT-11','時効期限内の8事故からPL法の賠償責任に該当しない数を求める。','pl_scope',['scope','attachment','software','processing','producer','repair'], 'アの冷蔵庫から住宅への延焼、ウの製造欠陥のあるエスカレータ、オの組込みソフトのロボット、キの輸入加工品の生ハムは対象となる。イの土地建売住宅の施工不良、エの電力、カの未加工自然養殖活魚、クの後の保守作業ミスは対象外で4件となり候補4である。時効期限内という明示条件により期間判定をここで追加しない。','全事例は時効期限内。対象外数候補1、2、3、4、5。',counts=[1,2,3,4,5])
add('R05-REG-APT-06','付合・組込みソフト・原子力・修理・海外共通化の5記述を判定する。','pl_scope',['attachment','software','otherlaw','repair'], 'アのエスカレータはいかなる場合も対象外という断定は誤りである。イの組込み製品の因果関係、ウの原子力特別法、エの性質回復維持という修理サービスの除外は正しい。オの日本法だけで海外対応できるという説明は誤りである。FTTTFが候補3に対応する。エは修理された元の製品自体の対象性を一括して否定する文として読まない。','列順ア・イ・ウ・エ・オ。特別法と修理サービスを区別。',vector='FTTTF',rows=['TFTTF','TTFFT','FTTTF','FFTTF','FFFFT'],citations=['pl_statute','pl_qa','pl_definitions2018','pl_nuclear_statute'])
